import { useState } from 'react';
import {
  call,
  Band,
  Badge,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Form,
  Tiles,
  Num,
} from '../kit';
import type { PageProps, Row } from '../kit';

type Mode = '' | 'aggregate' | 'close' | 'dailyClose' | 'dailyCancel' | 'cancel';

export default function FnSfr01804Page({ role, notify }: PageProps) {
  const [mode, setMode] = useState<Mode>('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [workDate, setWorkDate] = useState('');
  const [summary, setSummary] = useState<Row | undefined>(undefined);
  const [results, setResults] = useState<Row[]>([]);
  const [target, setTarget] = useState<Row | undefined>(undefined);

  function open(next: Mode) {
    setMode(next);
    setTarget(undefined);
  }

  function addResult(row: Row) {
    setResults((prev) => [{ ...row, key: String(Date.now()) + String(prev.length) }, ...prev]);
  }

  function requirePeriod() {
    if (!startDate || !endDate) {
      throw new Error('마감 시작일과 마감 종료일을 입력하세요.');
    }
  }

  function requireDate() {
    if (!workDate) {
      throw new Error('근무일자를 입력하세요.');
    }
  }

  async function aggregate() {
    requirePeriod();
    const res = await call('POST', '/attendance-closings/aggregate', role, {
      closingStartDate: startDate,
      closingEndDate: endDate,
    });
    setSummary(res);
    setMode('');
    notify('근태를 집계했습니다.');
  }

  async function closePeriod() {
    requirePeriod();
    const res = await call('POST', '/attendance-closings', role, {
      closingStartDate: startDate,
      closingEndDate: endDate,
    });
    addResult({
      kind: '기간 마감',
      attendanceClosingId: res.attendanceClosingId,
      period: startDate + ' ~ ' + endDate,
      closingStatus: res.closingStatus,
    });
    setMode('');
    notify('근태를 마감했습니다.');
  }

  async function cancelPeriod() {
    if (!target) {
      return;
    }
    const res = await call('POST', '/attendance-closings/' + String(target.attendanceClosingId) + '/cancel', role, {});
    setResults((prev) =>
      prev.map((row) => (row.key === target.key ? { ...row, closingStatus: res.closingStatus } : row)),
    );
    setMode('');
    setTarget(undefined);
    notify('근태 마감을 취소했습니다.');
  }

  async function closeDaily() {
    requireDate();
    const res = await call('POST', '/attendance-dailies/close', role, { workDate });
    addResult({ kind: '일별 마감', period: workDate, closingStatus: res.closingStatus });
    setMode('');
    notify('일별 근태를 마감했습니다.');
  }

  async function cancelDaily() {
    requireDate();
    const res = await call('POST', '/attendance-dailies/cancel-close', role, { workDate });
    addResult({ kind: '일별 마감취소', period: workDate, closingStatus: res.closingStatus });
    setMode('');
    notify('일별 근태 마감을 취소했습니다.');
  }

  const periodFields = (
    <>
      <Field label="마감 시작일" required>
        <DateInput value={startDate} onChange={setStartDate} />
      </Field>
      <Field label="마감 종료일" required>
        <DateInput value={endDate} onChange={setEndDate} />
      </Field>
    </>
  );

  const dateField = (
    <Field label="근무일자" required>
      <DateInput value={workDate} onChange={setWorkDate} />
    </Field>
  );

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>집계 현황</h2>
        <Tiles
          items={[
            ['집계 대상 근태', <Num value={summary ? summary.totalCount : 0} />],
            ['미승인·미처리', <Num value={summary ? summary.unprocessedCount : 0} />],
            ['처리 결과', <Num value={results.length} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>처리 결과</h2>
        <Band total={results.length}>
          <button type="button" onClick={() => open('aggregate')}>근태 집계</button>
          <button type="button" onClick={() => open('close')}>기간 마감</button>
          <button type="button" onClick={() => open('dailyClose')}>일별 마감</button>
          <button type="button" onClick={() => open('dailyCancel')}>일별 마감 취소</button>
        </Band>
        <DataTable
          rows={results}
          empty="처리한 내역이 없습니다."
          columns={[
            { key: 'kind', label: '구분' },
            {
              key: 'period',
              label: '기간·일자',
              render: (row) =>
                typeof row.period === 'string' && row.period.length === 10 ? (
                  <DateText value={row.period} />
                ) : (
                  String(row.period)
                ),
            },
            { key: 'closingStatus', label: '마감·승인 처리 상태', render: (row) => <Badge value={row.closingStatus} /> },
            {
              key: 'action',
              label: '처리',
              render: (row) =>
                row.kind === '기간 마감' && row.closingStatus === '마감' ? (
                  <button
                    type="button"
                    onClick={() => {
                      setTarget(row);
                      setMode('cancel');
                    }}
                  >
                    마감 취소
                  </button>
                ) : null,
            },
          ]}
        />
      </section>
      {mode === 'aggregate' && (
        <Drawer title="근태 집계" onClose={() => setMode('')}>
          <Form onSubmit={aggregate} submit="집계">
            {periodFields}
          </Form>
        </Drawer>
      )}
      {mode === 'close' && (
        <Drawer title="기간 마감" onClose={() => setMode('')}>
          <Form onSubmit={closePeriod} submit="마감">
            {periodFields}
          </Form>
        </Drawer>
      )}
      {mode === 'dailyClose' && (
        <Drawer title="일별 마감" onClose={() => setMode('')}>
          <Form onSubmit={closeDaily} submit="마감">
            {dateField}
          </Form>
        </Drawer>
      )}
      {mode === 'dailyCancel' && (
        <Drawer title="일별 마감 취소" onClose={() => setMode('')}>
          <Form onSubmit={cancelDaily} submit="마감 취소" danger>
            {dateField}
          </Form>
        </Drawer>
      )}
      {mode === 'cancel' && target && (
        <Drawer title="근태 마감 취소" onClose={() => setMode('')}>
          <Form
            onSubmit={cancelPeriod}
            submit="마감 취소"
            danger
            note={'기간 ' + String(target.period) + ' 마감을 취소합니다.'}
          />
        </Drawer>
      )}
    </div>
  );
}
